\ir _helpers/auth_session.sql
begin;
select no_plan();
-- Isolate public projections from unrelated local preview fixtures, without deleting them.
update private.commercial_resources set moderation_state='draft' where offering_code in('professional_profile','establishment_profile');
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('75000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','phase5-'||i||'@example.invalid','x',now(),'{}','{}',now(),now() from generate_series(1,4)i;
update public.users set usage_profile=case when id='75000000-0000-0000-0000-000000000002' then 'establishment_owner' else 'professional' end where id::text like '75000000-%';
update public.users set role='superadmin' where id='75000000-0000-0000-0000-000000000004';
create function pg_temp.pro_user(n integer) returns void language sql as $$select pg_temp.set_test_user(('75000000-0000-0000-0000-'||lpad(n::text,12,'0')),true)$$;
create function pg_temp.pro_admin() returns void language plpgsql as $$begin
 perform pg_temp.pro_user(4);perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from clock_timestamp())::bigint))))::text,true);
end$$;
create temp table pro_ids(k text primary key,v uuid);grant all on pro_ids to authenticated;grant select on pro_ids to anon;
create function pg_temp.pro_rev(k text) returns bigint language sql security definer set search_path='' as $$select d.version::bigint from public.professional_listing_drafts d where listing_id=(select v from pro_ids where pro_ids.k=$1)$$;
create function pg_temp.pro_data(kind text,name text,mid uuid default null) returns jsonb language sql as $$select jsonb_build_object('kind',kind,'displayName',name,'categoryKey',case when kind='space' then 'academia' else 'personal_trainer' end,'modalityKeys',jsonb_build_array('musculacao'),'specialties',jsonb_build_array('Treino de força'),'bio','Descrição sintética completa de apresentação.','city','São Paulo','uf','SP','serviceMode','in_person','contacts',jsonb_build_object('website','https://example.invalid/contact'),'mediaId',mid,'address',case when kind='space' then 'Rua de Teste, 100' else '' end,'openingHours',case when kind='space' then 'Segunda a sexta, 8h às 18h' else '' end)$$;
select pg_temp.pro_admin();
select public.admin_publish_commercial_price('professional_profile','5',1,30,null,(select revision from public.commercial_offerings where code='professional_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_publish_commercial_price('establishment_profile','8',1,30,null,(select revision from public.commercial_offerings where code='establishment_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_set_commercial_sales('professional_profile',true,(select revision from public.commercial_offerings where code='professional_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public.admin_set_commercial_sales('establishment_profile',true,(select revision from public.commercial_offerings where code='establishment_profile'),gen_random_uuid(),'Synthetic Phase 5 fixture only',true);
select public._wallet_credit_cash('75000000-0000-0000-0000-000000000001',100);
select public._ledger_record('75000000-0000-0000-0000-000000000001','phase5-fixture-pro','cash','credit',100,'synthetic','fixture','phase5');
select public._wallet_credit_cash('75000000-0000-0000-0000-000000000002',100);
select public._ledger_record('75000000-0000-0000-0000-000000000002','phase5-fixture-space','cash','credit',100,'synthetic','fixture','phase5');
select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('pro',(public.create_professional_listing('professional')->>'listingId')::uuid);
select is(public.create_professional_listing('professional')->>'created','false','creation replay preserves identity');
select throws_ok($$select public.create_professional_listing('space')$$,'ALREADY_EXISTS','existing one-listing constraint preserved');
select is(public.get_my_professional_listing()->'draft'->>'version','0','new draft can be empty and free');
select public.save_professional_listing_draft((select v from pro_ids where k='pro'),'{"kind":"professional","displayName":"Partial"}',0);
select is(public.get_my_professional_listing()->'draft'->>'displayName','Partial','incomplete draft can be saved for free');
select throws_ok($$select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),1,'submitted')$$,'DRAFT_INCOMPLETE','submission requires useful complete content');
select throws_ok($$select public.quote_commercial_order((select v from pro_ids where k='pro'),'2',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','unapproved draft cannot be charged');
select throws_ok($$select public.prepare_professional_listing_publish((select v from pro_ids where k='pro'),'legacy')$$,'EDITORIAL_REVIEW_REQUIRED','old direct publish path fails closed');
select throws_ok($$select public.save_professional_listing_draft((select v from pro_ids where k='pro'),'{}')$$,'EDITORIAL_REVISION_REQUIRED','old no-CAS edit cannot overwrite content');
select throws_ok($$select * from public.professional_listing_drafts$$,'42501',null,'client cannot bypass authorized getters');
select throws_ok($$select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),1,'approved','Attempt self approval')$$,'42501','PERMISSION_DENIED','owner cannot approve itself');
reset role;
insert into public.storefront_media(id,storefront_id,storage_path,state,width,height,byte_size)
select '75100000-0000-0000-0000-000000000001',v,v||'/75100000-0000-0000-0000-000000000001.webp','ready',32,32,100 from pro_ids where k='pro';
select pg_temp.pro_user(1);set local role authenticated;
select public.save_professional_listing_draft((select v from pro_ids where k='pro'),pg_temp.pro_data('professional','Profissional aprovado','75100000-0000-0000-0000-000000000001'),1);
select throws_ok($$select public.save_professional_listing_draft((select v from pro_ids where k='pro'),pg_temp.pro_data('professional','Stale'),1)$$,'EDITORIAL_REVISION_CONFLICT','stale edits rejected');
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),2,'submitted');
reset role;select pg_temp.pro_user(2);set local role authenticated;
insert into pro_ids values('space',(public.create_professional_listing('space')->>'listingId')::uuid);
select public.save_professional_listing_draft((select v from pro_ids where k='space'),pg_temp.pro_data('space','Estabelecimento aprovado'),0);
select public.set_professional_listing_editorial((select v from pro_ids where k='space'),1,'submitted');
select throws_ok($$select public.save_professional_listing_draft((select v from pro_ids where k='pro'),pg_temp.pro_data('professional','Foreign'),3)$$,'LISTING_NOT_FOUND','owner cannot edit another professional');
reset role;select pg_temp.pro_admin();set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),3,'approved','Approve synthetic professional');
select public.set_professional_listing_editorial((select v from pro_ids where k='space'),2,'approved','Approve synthetic establishment');
select throws_ok($$select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),3,'approved','Concurrent stale approval')$$,'EDITORIAL_REVISION_CONFLICT','stale administrative decision rejected');
reset role;
select is((select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001'),100,'create edit and moderation do not debit');
select pg_temp.set_test_user(null,true);set local role anon;
select is(public.public_get_professional((select v from pro_ids where k='pro')),null::jsonb,'approved but unpaid stays private');
select is(public.authorize_storefront_media('75100000-0000-0000-0000-000000000001'),null::text,'unpaid image stays private');
select throws_ok($$select * from public.published_professional_listings$$,'42501',null,'public table read cannot bypass entitlement');
select throws_ok($$select public.admin_get_professional_listing((select v from pro_ids where k='pro'))$$,'42501',null,'guest cannot read admin draft');
reset role;select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('order-pro',(public.quote_commercial_order((select v from pro_ids where k='pro'),'2',gen_random_uuid())->>'id')::uuid);
select is(public.confirm_commercial_order((select v from pro_ids where k='order-pro'),true)->>'totalCash','10','professional uses independent daily price');
select public.confirm_commercial_order((select v from pro_ids where k='order-pro'),true);
reset role;select pg_temp.pro_user(2);set local role authenticated;
insert into pro_ids values('order-space',(public.quote_commercial_order((select v from pro_ids where k='space'),'3',gen_random_uuid())->>'id')::uuid);
select is(public.confirm_commercial_order((select v from pro_ids where k='order-space'),true)->>'totalCash','24','establishment uses independent daily price');
select throws_ok($$select public.quote_commercial_order((select v from pro_ids where k='pro'),'1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','one owner cannot buy another resource');
reset role;
select is((select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001'),90,'confirmation replay debits exactly once');
select is((select expires_at-starts_at from public.visibility_entitlements where resource_id=(select v from pro_ids where k='pro')),interval '48 hours','each day is 24 hours');
select throws_ok($$update public.professional_listings set kind='space' where id=(select v from pro_ids where k='pro')$$,'LISTING_IDENTITY_IMMUTABLE','resource kind cannot change to reuse another tariff');
select throws_ok($$update public.professional_listings set owner_id='75000000-0000-0000-0000-000000000002' where id=(select v from pro_ids where k='pro')$$,'LISTING_IDENTITY_IMMUTABLE','ownership cannot be reassigned silently');
select pg_temp.set_test_user(null,true);set local role anon;
select is(public.public_get_professional((select v from pro_ids where k='pro'))->>'displayName','Profissional aprovado','paid approved professional is public');
select is(public.public_get_professional((select v from pro_ids where k='space'))->>'address','Rua de Teste, 100','approved establishment exposes its public address');
select is(jsonb_array_length(public.public_list_professionals('professional')->'items'),1,'professional directory excludes establishments');
select is(jsonb_array_length(public.public_list_professionals('space')->'items'),1,'establishment directory excludes professionals');
select is(jsonb_array_length(public.public_list_professionals('professional','corrida')->'items'),0,'modality filter stays on server');
select ok(not(public.public_get_professional((select v from pro_ids where k='pro')) ? 'ownerId'),'public detail omits private owner identifier');
select ok(public.authorize_storefront_media('75100000-0000-0000-0000-000000000001') is not null,'public approved image goes through the shared gateway');
select is(public.public_professional_avatar_visible('legacy/personal.webp'),false,'personal avatar policy cannot bypass paid media');
select is(jsonb_array_length(public.public_listing_sitemap()->'items'),2,'sitemap contains only both eligible resources');
reset role;
create temp table pro_finance_before as select (select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001')balance,(select to_jsonb(e) from public.visibility_entitlements e where resource_id=(select v from pro_ids where k='pro'))entitlement;
select pg_temp.pro_user(1);set local role authenticated;
select public.save_professional_listing_draft((select v from pro_ids where k='pro'),pg_temp.pro_data('professional','PRIVATE PENDING NAME'),4);
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),5,'submitted');
reset role;select pg_temp.set_test_user(null,true);set local role anon;
select is(public.public_get_professional((select v from pro_ids where k='pro'))->>'displayName','Profissional aprovado','editing does not interrupt paid approved version');
select ok(public.authorize_storefront_media('75100000-0000-0000-0000-000000000001') is not null,'removing draft image preserves approved public bytes');
reset role;select pg_temp.pro_admin();set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),6,'rejected','Reject pending synthetic revision');
reset role;
select is((select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001'),(select balance from pro_finance_before),'editorial changes never move money');
select is((select to_jsonb(e) from public.visibility_entitlements e where resource_id=(select v from pro_ids where k='pro')),(select entitlement from pro_finance_before),'editorial changes never extend or reset contracts');
select is(public.public_get_professional((select v from pro_ids where k='pro'))->>'displayName','Profissional aprovado','rejection keeps approved publication');
select throws_ok($$delete from public.storefront_media where id='75100000-0000-0000-0000-000000000001'$$,'23503',null,'foreign key prevents deleting media used by approved version');
select pg_temp.pro_user(1);set local role authenticated;
select is(public.discard_unused_storefront_media('75100000-0000-0000-0000-000000000001'),null::text,'discard checks public references');
insert into pro_ids values('renew',(public.quote_commercial_order((select v from pro_ids where k='pro'),'1',gen_random_uuid())->>'id')::uuid);
select public.confirm_commercial_order((select v from pro_ids where k='renew'),true);
reset role;
select is((select expires_at-starts_at from public.visibility_entitlements where resource_id=(select v from pro_ids where k='pro')),interval '72 hours','renewal during pending/rejected draft extends existing period only');
select pg_temp.pro_user(1);set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),7,'submitted');
reset role;
update public.visibility_entitlements set starts_at=clock_timestamp()-interval '10 days',expires_at=clock_timestamp()-interval '1 second' where resource_id=(select v from pro_ids where k='pro');
select pg_temp.pro_admin();set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='pro'),8,'approved','Approve after contract expired');
reset role;select pg_temp.set_test_user(null,true);set local role anon;
select is(public.public_get_professional((select v from pro_ids where k='pro')),null::jsonb,'approval after expiry does not reactivate');
select is(public.authorize_storefront_media('75100000-0000-0000-0000-000000000001'),null::text,'expired image cannot be accessed directly');
select is(jsonb_array_length(public.public_listing_sitemap()->'items'),1,'expired resource removed from sitemap');
reset role;select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('after-expiry',(public.quote_commercial_order((select v from pro_ids where k='pro'),'1',gen_random_uuid())->>'id')::uuid);
select public.confirm_commercial_order((select v from pro_ids where k='after-expiry'),true);
reset role;
select is((select expires_at-starts_at from public.visibility_entitlements where resource_id=(select v from pro_ids where k='pro')),interval '24 hours','expired renewal starts a new paid period');
select is(public.public_get_professional((select v from pro_ids where k='pro'))->>'displayName','PRIVATE PENDING NAME','only admin-approved revision replaces public snapshot');
select pg_temp.pro_user(2);set local role authenticated;
insert into pro_ids values('pending-space-order',(public.quote_commercial_order((select v from pro_ids where k='space'),'1',gen_random_uuid())->>'id')::uuid);
reset role;select pg_temp.pro_admin();set local role authenticated;
select public.set_professional_listing_editorial((select v from pro_ids where k='space'),3,'suspended','Suspend synthetic establishment');
reset role;select pg_temp.pro_user(2);set local role authenticated;
select throws_ok($$select public.confirm_commercial_order((select v from pro_ids where k='pending-space-order'),true)$$,'RESOURCE_NOT_ELIGIBLE','payment cannot remove suspension');
select throws_ok($$select public.set_professional_listing_editorial((select v from pro_ids where k='space'),4,'draft','Attempt to remove suspension')$$,'42501','PERMISSION_DENIED','only recent superadmin can remove suspension');
reset role;select pg_temp.set_test_user(null,true);set local role anon;
select is(public.public_get_professional((select v from pro_ids where k='space')),null::jsonb,'suspended establishment excluded from direct API');
reset role;
select pg_temp.pro_user(1);set local role authenticated;
insert into pro_ids values('insufficient',(public.quote_commercial_order((select v from pro_ids where k='pro'),'30',gen_random_uuid())->>'id')::uuid);
select throws_ok($$select public.confirm_commercial_order((select v from pro_ids where k='insufficient'),true)$$,'Saldo de EvoCash insuficiente.','adapter uses atomic shared insufficient-balance guard');
reset role;
select is((select cash_balance from public.wallets where user_id='75000000-0000-0000-0000-000000000001'),80,'insufficient balance never partially debits');
select is((select offering_code from public.professional_listings where id=(select v from pro_ids where k='pro')),'professional_profile','professional anchor binds its generated offering');
select is((select offering_code from public.professional_listings where id=(select v from pro_ids where k='space')),'establishment_profile','establishment anchor binds its independent offering');
insert into public.account_restrictions(user_id,action,until)values('75000000-0000-0000-0000-000000000001','temporary_suspension',clock_timestamp()+interval '1 day');
select is(public.public_get_professional((select v from pro_ids where k='pro')),null::jsonb,'restricted account hidden by relational eligibility');
select pg_temp.pro_user(1);set local role authenticated;
select throws_ok($$select public.get_my_professional_listing()$$,'APP_ACCESS_DENIED','blocked account cannot mutate or read private management');
reset role;
select ok(not has_function_privilege('authenticated','public.finalize_professional_listing_publish(uuid,text,text,uuid)','execute'),'retired finalizer cannot publish even through direct RPC');
select ok(not has_function_privilege('anon','private.listing_record(uuid)','execute'),'private snapshot serializer has no public execution');
select ok(not has_table_privilege('authenticated','public.storefront_media','update'),'clients cannot attest or delete media directly');
select * from finish();rollback;
